import { useEffect, useMemo, useState } from "react";
import { useAuth } from "@/_core/hooks/useAuth";
import { trpc } from "@/lib/trpc";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Loader2, MapPin, Menu, Search, Sparkles, Users, Leaf, Bell, ArrowUpRight, Route as RouteIcon, X, Plus, LogOut, ShieldCheck, Navigation, ChevronRight } from "lucide-react";

const navItems = ["Home", "Find", "Matches", "Create", "My Rides", "Impact", "Command Center", "Profile", "Notifications", "Settings"];
const formatStops = (value?: string | null) => { try { return value ? JSON.parse(value) as string[] : []; } catch { return value ? value.split(",").map((s) => s.trim()).filter(Boolean) : []; } };

export default function Home() {
  const { user, loading, isAuthenticated, logout: authLogout } = useAuth();
  const [active, setActive] = useState("Home");
  const [mobileNav, setMobileNav] = useState(false);
  const [search, setSearch] = useState("");
  const [routeType, setRouteType] = useState<"all" | "campus" | "local">("all");
  const [rideDate, setRideDate] = useState("");
  const [selectedRouteId, setSelectedRouteId] = useState<number | null>(null);
  const [toast, setToast] = useState("");
  const [poolForm, setPoolForm] = useState({ routeId: "", pickupPoint: "", departureTime: "08:00", capacity: "4" });
  const [rideForm, setRideForm] = useState({ routeId: "", pickupPoint: "", destination: "SASI Main Gate", date: "", time: "08:00", availableSeats: "3", notes: "", vehicleType: "Car", genderPreference: "any", contactPreference: "In-app" });
  const [authMode, setAuthMode] = useState<"login" | "signup" | "recovery" | "">("");
  const [authForm, setAuthForm] = useState({ name: "", email: "", password: "", college: "", course: "", city: "", pickupPoint: "", phoneNumber: "", studyYear: "", gender: "", genderPreference: "any" });
  const [authError, setAuthError] = useState("");
  const [recoveryEmail, setRecoveryEmail] = useState("");

  const routeInput = useMemo(() => ({ query: search || undefined, routeType: routeType === "all" ? undefined : routeType }), [search, routeType]);
  const routesQuery = trpc.routes.list.useQuery(routeInput);
  const registeredCountQuery = trpc.auth.registeredCount.useQuery();
  const poolsQuery = trpc.pools.list.useQuery(undefined);
  const joinedPoolsQuery = trpc.pools.mine.useQuery(undefined, { enabled: isAuthenticated });
  const impactQuery = trpc.impact.summary.useQuery();
  const ridesQuery = trpc.rides.list.useQuery(undefined, { enabled: isAuthenticated });
  const requestsQuery = trpc.rides.requests.useQuery(undefined, { enabled: isAuthenticated });
  const discoverRidesQuery = trpc.rides.discover.useQuery({ query: search || undefined, routeType: routeType === "all" ? undefined : routeType, date: rideDate || undefined }, { enabled: isAuthenticated });
  const profileQuery = trpc.profile.me.useQuery(undefined, { enabled: isAuthenticated });
  const seedMutation = trpc.routes.seed.useMutation();
  const authUtils = trpc.useUtils();
  const signup = trpc.auth.signup.useMutation({ onSuccess: () => { setAuthMode(""); setAuthError(""); authUtils.auth.me.invalidate(); setToast("Account created. Welcome to SmartRide."); }, onError: (e) => setAuthError(e.message) });
  const login = trpc.auth.login.useMutation({ onSuccess: () => { setAuthMode(""); setAuthError(""); authUtils.auth.me.invalidate(); setToast("Welcome back."); }, onError: (e) => setAuthError(e.message) });
  const utils = trpc.useUtils();
  const handleLogout = async () => { await authLogout(); utils.rides.list.setData(undefined, undefined); utils.pools.mine.setData(undefined, undefined); utils.profile.me.setData(undefined, undefined); utils.notifications.list.setData(undefined, undefined); setActive("Home"); setSelectedRouteId(null); };
  useEffect(() => { if (!isAuthenticated && ["Create", "My Rides", "Profile", "Notifications", "Matches", "Settings"].includes(active)) { setActive("Home"); setSelectedRouteId(null); } }, [isAuthenticated, active]);
  const joinPool = trpc.pools.join.useMutation({ onSuccess: () => { setToast("You are in. The pool has been updated."); utils.pools.list.invalidate(); }, onError: (e) => setToast(e.message) });
  const createPool = trpc.pools.create.useMutation({ onSuccess: () => { setToast("Smart Pool created."); utils.pools.list.invalidate(); setActive("Find"); }, onError: (e) => setToast(e.message) });
  const createRide = trpc.rides.create.useMutation({ onSuccess: () => { setToast("Ride saved to My Rides."); utils.rides.list.invalidate(); setActive("My Rides"); }, onError: (e) => setToast(e.message) });
  const cancelRide = trpc.rides.cancel.useMutation({ onSuccess: () => { setToast("Ride cancelled."); utils.rides.list.invalidate(); }, onError: (e) => setToast(e.message) });
  const leavePool = trpc.pools.leave.useMutation({ onSuccess: () => { setToast("You left the Smart Pool."); utils.pools.mine.invalidate(); }, onError: (e) => setToast(e.message) });
  const updateProfile = trpc.profile.update.useMutation({ onSuccess: () => { setToast("Profile updated."); utils.profile.me.invalidate(); }, onError: (e) => setToast(e.message) });
  const requestRide = trpc.rides.request.useMutation({ onSuccess: () => { setToast("Ride request sent."); utils.rides.requests.invalidate(); utils.notifications.list.invalidate(); }, onError: (e) => setToast(e.message) });
  const updateRequest = trpc.rides.updateRequest.useMutation({ onSuccess: () => { setToast("Request updated."); utils.rides.requests.invalidate(); utils.notifications.list.invalidate(); }, onError: (e) => setToast(e.message) });

  useEffect(() => { seedMutation.mutate(); }, []);
  useEffect(() => { if (!toast) return; const id = window.setTimeout(() => setToast(""), 3600); return () => window.clearTimeout(id); }, [toast]);
  const routes = routesQuery.data ?? [];
  const pools = poolsQuery.data ?? [];
  const selectedRoute = routes.find((r) => r.id === selectedRouteId) ?? null;
  const impact = impactQuery.data;

  const go = (item: string) => { setActive(item); setMobileNav(false); window.scrollTo({ top: 0, behavior: "smooth" }); };
  const protectedAction = (item: string) => { if (!isAuthenticated) { setAuthMode("login"); setAuthError(""); return; } go(item); };

  if (loading) return <div className="min-h-screen grid place-items-center bg-[#071022] text-cyan-200"><Loader2 className="animate-spin" /></div>;

  return <div className="app-shell min-h-screen bg-[#071022] text-slate-100">{authMode && <div className="fixed inset-0 z-50 grid place-items-center bg-[#030817]/80 p-5 backdrop-blur-md"><div className="glass w-full max-w-lg rounded-[2rem] p-7 md:p-9"><div className="flex items-start justify-between gap-4"><div><div className="eyebrow">SASI SmartRide accounts</div><h2 className="mt-2 text-3xl font-bold text-white">{authMode === "login" ? "Welcome back." : authMode === "recovery" ? "Recover your account." : "Join the network."}</h2><p className="mt-2 text-sm text-slate-400">{authMode === "login" ? "Sign in to access your rides, pools, and profile." : authMode === "recovery" ? "Recover your account with a verified email link." : "Create your own account. Your data stays private to you."}</p>{authMode === "recovery" && <div className="mt-4 rounded-xl border border-amber-300/20 bg-amber-300/10 px-3 py-2 text-sm text-amber-100">Email verification is staged but disabled until a verified sending domain and sender are configured.</div>}{authMode === "signup" && registeredCountQuery.data === 0 && <div className="mt-4 rounded-xl border border-cyan-300/15 bg-cyan-300/5 px-3 py-2 text-sm text-cyan-100">No students have joined yet. Create an account to get started.</div>}</div><button onClick={() => setAuthMode("")} className="rounded-full p-2 text-slate-400 hover:bg-white/10"><X size={18} /></button></div>{authError && <div className="mt-6 rounded-xl border border-rose-300/20 bg-rose-300/10 px-3 py-2 text-sm text-rose-100">{authError}</div>}<div className="mt-6 grid gap-4">{authMode === "signup" && <><Field label="Name"><Input value={authForm.name} onChange={(e) => setAuthForm({ ...authForm, name: e.target.value })} placeholder="Your name" /></Field><div className="grid gap-4 sm:grid-cols-2"><Field label="College"><Input value={authForm.college} onChange={(e) => setAuthForm({ ...authForm, college: e.target.value })} placeholder="SASI Institute" /></Field><Field label="Course"><Input value={authForm.course} onChange={(e) => setAuthForm({ ...authForm, course: e.target.value })} placeholder="Computer Science" /></Field></div><div className="grid gap-4 sm:grid-cols-2"><Field label="City"><Input value={authForm.city} onChange={(e) => setAuthForm({ ...authForm, city: e.target.value })} placeholder="Tadepalligudem" /></Field><Field label="Pickup point"><Input value={authForm.pickupPoint} onChange={(e) => setAuthForm({ ...authForm, pickupPoint: e.target.value })} placeholder="Railway Station" /></Field></div><div className="grid gap-4 sm:grid-cols-2"><Field label="Phone"><Input value={authForm.phoneNumber} onChange={(e) => setAuthForm({ ...authForm, phoneNumber: e.target.value })} placeholder="Optional phone number" /></Field><Field label="Study year"><Input value={authForm.studyYear} onChange={(e) => setAuthForm({ ...authForm, studyYear: e.target.value })} placeholder="2nd year" /></Field></div><div className="grid gap-4 sm:grid-cols-2"><Field label="Gender"><Input value={authForm.gender} onChange={(e) => setAuthForm({ ...authForm, gender: e.target.value })} placeholder="Optional" /></Field><Field label="Match preference"><select value={authForm.genderPreference} onChange={(e) => setAuthForm({ ...authForm, genderPreference: e.target.value })} className="h-10 w-full rounded-md border border-white/10 bg-white/5 px-3 text-sm text-white"><option className="bg-[#10213a]">any</option><option className="bg-[#10213a]">same-gender</option></select></Field></div></>}<Field label="Email"><Input type="email" value={authForm.email} onChange={(e) => setAuthForm({ ...authForm, email: e.target.value })} placeholder="you@example.com" /></Field>{authMode !== "recovery" && <Field label="Password"><Input type="password" value={authForm.password} onChange={(e) => setAuthForm({ ...authForm, password: e.target.value })} placeholder="At least 8 characters" /></Field>}<Button disabled={authMode === "recovery" || signup.isPending || login.isPending} onClick={() => authMode === "recovery" ? setAuthError("Recovery email delivery is not enabled yet. Configure Resend before requesting a reset.") : authMode === "signup" ? signup.mutate(authForm) : login.mutate({ email: authForm.email, password: authForm.password })} className="mt-2 rounded-xl bg-cyan-300 text-slate-950 hover:bg-cyan-200">{signup.isPending || login.isPending ? <Loader2 className="animate-spin" /> : authMode === "recovery" ? "Recovery email unavailable" : authMode === "login" ? "Log in" : "Create account"}</Button>{authMode !== "signup" && <button onClick={() => { setAuthMode(authMode === "recovery" ? "login" : "recovery"); setAuthError(""); }} className="text-sm text-cyan-200 hover:text-white">{authMode === "recovery" ? "Back to log in" : "Forgot password?"}</button>}<button onClick={() => { setAuthMode(authMode === "login" ? "signup" : "login"); setAuthError(""); }} className="text-sm text-cyan-200 hover:text-white">{authMode === "login" ? "New here? Create an account" : "Already have an account? Log in"}</button></div></div></div>}<div className="network-bg" aria-hidden="true"><svg className="route-network" viewBox="0 0 1000 700" preserveAspectRatio="none"><defs><linearGradient id="route-cyan" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stopColor="#55e9da" stopOpacity="0" /><stop offset="0.45" stopColor="#55e9da" stopOpacity="0.58" /><stop offset="1" stopColor="#8be9ff" stopOpacity="0.9" /></linearGradient><filter id="route-glow"><feGaussianBlur stdDeviation="5" result="blur" /><feMerge><feMergeNode in="blur" /><feMergeNode in="SourceGraphic" /></feMerge></filter></defs><g className="route-paths" fill="none" stroke="url(#route-cyan)" strokeWidth="1.4"><path id="route-a" d="M 20 120 C 220 150, 430 210, 720 330" /><path id="route-b" d="M 820 65 C 790 160, 760 245, 720 330" /><path id="route-c" d="M 980 500 C 860 455, 790 385, 720 330" /><path id="route-d" d="M 95 610 C 260 520, 510 410, 720 330" /><path id="route-e" d="M 470 0 C 540 120, 650 230, 720 330" /></g><g className="route-pulses" fill="#b4fff5" filter="url(#route-glow)"><circle r="4"><animateMotion dur="7s" repeatCount="indefinite"><mpath href="#route-a" /></animateMotion></circle><circle r="3"><animateMotion dur="9s" begin="-3s" repeatCount="indefinite"><mpath href="#route-b" /></animateMotion></circle><circle r="4"><animateMotion dur="8s" begin="-5s" repeatCount="indefinite"><mpath href="#route-c" /></animateMotion></circle><circle r="3"><animateMotion dur="10s" begin="-2s" repeatCount="indefinite"><mpath href="#route-d" /></animateMotion></circle><circle r="3"><animateMotion dur="8.5s" begin="-6s" repeatCount="indefinite"><mpath href="#route-e" /></animateMotion></circle></g><g className="campus-beacon" transform="translate(720 330)"><circle r="18" /><circle r="7" /><path d="M0-30v60M-30 0h60" /></g></svg><span className="network-node left-[12%] top-[22%]" /><span className="network-node left-[74%] top-[18%] [animation-delay:1s]" /><span className="network-node left-[83%] top-[58%] [animation-delay:1.6s]" /><span className="network-node left-[22%] top-[64%] [animation-delay:2.2s]" /><span className="campus-label">SASI CAMPUS</span></div>
    <header className="sticky top-0 z-30 border-b border-white/10 bg-[#071022]/75 backdrop-blur-xl"><div className="mx-auto flex max-w-7xl items-center justify-between px-5 py-4 lg:px-8"><button onClick={() => go("Home")} className="flex items-center gap-3 text-left"><span className="grid h-10 w-10 place-items-center rounded-2xl bg-cyan-300 text-slate-950 shadow-[0_0_30px_rgba(44,229,212,.22)]"><Navigation size={20} /></span><span><span className="block font-['Space_Grotesk'] text-base font-bold tracking-tight">SASI <span className="text-cyan-300">SmartRide</span></span><span className="block text-[10px] uppercase tracking-[.2em] text-slate-500">Campus mobility network</span></span></button><nav className="hidden items-center gap-1 lg:flex">{navItems.map((item) => <button key={item} onClick={() => ["Create", "My Rides", "Profile", "Notifications", "Settings", "Matches"].includes(item) ? protectedAction(item) : go(item)} className={`rounded-full px-3 py-2 text-sm ${active === item ? "bg-white/10 text-cyan-200" : "text-slate-400 hover:text-white"}`}>{item}</button>)}</nav><div className="flex items-center gap-2"><button onClick={() => protectedAction("Notifications")} className="relative rounded-full p-2 text-slate-400 hover:bg-white/10 hover:text-white"><Bell size={18} /></button>{isAuthenticated ? <button onClick={() => void handleLogout()} className="hidden items-center gap-2 rounded-full border border-white/10 px-3 py-2 text-xs text-slate-300 sm:flex"><span className="grid h-6 w-6 place-items-center rounded-full bg-cyan-300 font-bold text-slate-950">{user?.name?.[0] ?? "S"}</span>{user?.name?.split(" ")[0] ?? "Account"}<LogOut size={14} /></button> : <Button size="sm" onClick={() => { setAuthMode("login"); setAuthError(""); }} className="hidden rounded-full bg-cyan-300 text-slate-950 hover:bg-cyan-200 sm:flex">Sign in</Button>}<button onClick={() => setMobileNav((v) => !v)} className="rounded-full p-2 text-slate-300 lg:hidden">{mobileNav ? <X size={20} /> : <Menu size={20} />}</button></div></div>{mobileNav && <div className="border-t border-white/10 px-5 py-3 lg:hidden">{navItems.map((item) => <button key={item} onClick={() => ["Create", "My Rides", "Profile", "Notifications", "Settings", "Matches"].includes(item) ? protectedAction(item) : go(item)} className="block w-full border-b border-white/5 py-3 text-left text-sm text-slate-300">{item}</button>)}</div>}</header>

    <main className="mx-auto max-w-7xl px-5 pb-24 pt-10 lg:px-8">
      {toast && <div className="fixed right-5 top-24 z-50 flex max-w-sm items-center gap-3 rounded-2xl border border-cyan-300/20 bg-[#10223c] px-4 py-3 text-sm text-cyan-100 shadow-2xl"><ShieldCheck size={18} className="text-cyan-300" />{toast}</div>}{active !== "Home" && poolsQuery.isError && <div className="mb-6 rounded-2xl border border-rose-300/20 bg-rose-300/10 px-4 py-3 text-sm text-rose-100">Smart Pool data could not be loaded.</div>}
      {active === "Home" && <HomeView go={go} protectedAction={protectedAction} routes={routes} pools={pools} impact={impact} onRoute={(id: number) => { setSelectedRouteId(id); go("Route detail"); }} />}
      {active === "Find" && <FindView search={search} setSearch={setSearch} routeType={routeType} setRouteType={setRouteType} rideDate={rideDate} setRideDate={setRideDate} routes={routes} pools={pools} rides={discoverRidesQuery.data ?? []} ridesLoading={discoverRidesQuery.isLoading} ridesError={discoverRidesQuery.isError} routeError={routesQuery.isError} onRoute={(id: number) => { setSelectedRouteId(id); go("Route detail"); }} onRequest={(id: number) => requestRide.mutate({ rideId: id })} onJoin={(id: number) => { if (!isAuthenticated) { setAuthMode("login"); setAuthError(""); } else joinPool.mutate({ id }); }} />}
      {active === "Routes" && <FindView search={search} setSearch={setSearch} routeType={routeType} setRouteType={setRouteType} rideDate={rideDate} setRideDate={setRideDate} routes={routes} pools={pools} rides={discoverRidesQuery.data ?? []} ridesLoading={discoverRidesQuery.isLoading} ridesError={discoverRidesQuery.isError} routeError={routesQuery.isError} onRoute={(id: number) => { setSelectedRouteId(id); go("Route detail"); }} onRequest={(id: number) => requestRide.mutate({ rideId: id })} onJoin={(id: number) => { if (!isAuthenticated) { setAuthMode("login"); setAuthError(""); } else joinPool.mutate({ id }); }} />}
      {active === "Route detail" && selectedRoute && <RouteDetail route={selectedRoute} pools={pools.filter((p) => p.pool.routeId === selectedRoute.id)} onBack={() => go("Find")} />}
      {active === "Create" && <CreateView routes={routes} poolForm={poolForm} setPoolForm={setPoolForm} rideForm={rideForm} setRideForm={setRideForm} onCreatePool={() => createPool.mutate({ routeId: Number(poolForm.routeId), pickupPoint: poolForm.pickupPoint, departureTime: poolForm.departureTime, capacity: Number(poolForm.capacity) })} onCreateRide={() => createRide.mutate({ routeId: Number(rideForm.routeId), pickupPoint: rideForm.pickupPoint, destination: rideForm.destination, date: rideForm.date, time: rideForm.time, availableSeats: Number(rideForm.availableSeats), notes: rideForm.notes, vehicleType: rideForm.vehicleType, genderPreference: rideForm.genderPreference, contactPreference: rideForm.contactPreference })} busy={createPool.isPending || createRide.isPending} />}
      {active === "My Rides" && isAuthenticated && <div className="space-y-10"><RidesView rides={ridesQuery.data ?? []} joinedPools={joinedPoolsQuery.data ?? []} loading={ridesQuery.isLoading || joinedPoolsQuery.isLoading} error={ridesQuery.isError || joinedPoolsQuery.isError} onCancel={(id: number) => cancelRide.mutate({ id })} onLeave={(id: number) => leavePool.mutate({ id })} /><RequestBoard requests={requestsQuery.data} loading={requestsQuery.isLoading} onRequestStatus={(id: number, status: "accepted" | "rejected" | "cancelled") => updateRequest.mutate({ id, status })} /></div>}
      {active === "Impact" && <ImpactView impact={impact} error={impactQuery.isError} />}
      {active === "Command Center" && <CommandView />}
      {active === "Profile" && isAuthenticated && <ProfileView profile={profileQuery.data} error={profileQuery.isError} routes={routes} onSave={(data: any) => updateProfile.mutate(data)} busy={updateProfile.isPending} />}
      {active === "Notifications" && isAuthenticated && <NotificationsView />}
      {active === "Settings" && isAuthenticated && <SettingsView profile={profileQuery.data} />}
      {active === "Matches" && isAuthenticated && <MatchesView rides={discoverRidesQuery.data ?? []} loading={discoverRidesQuery.isLoading} error={discoverRidesQuery.isError} onRequest={(id: number) => requestRide.mutate({ rideId: id })} />}
    </main>
    <footer className="border-t border-white/10 px-5 py-8 text-center text-xs text-slate-500"><span className="text-cyan-300">SASI SmartRide</span> · Move smarter. Travel together.</footer>
  </div>;
}

function SectionHeading({ eyebrow, title, action }: { eyebrow: string; title: string; action?: React.ReactNode }) { return <div className="mb-6 flex items-end justify-between gap-4"><div><div className="eyebrow mb-2">{eyebrow}</div><h2 className="text-2xl font-bold text-white md:text-3xl">{title}</h2></div>{action}</div>; }
function HomeView({ go, protectedAction, routes, pools, impact, onRoute }: any) { return <div className="space-y-20"><section className="grid items-center gap-12 pb-10 pt-10 lg:grid-cols-[1.12fr_.88fr] lg:pt-20"><div><Badge className="mb-6 rounded-full border border-cyan-300/20 bg-cyan-300/10 px-3 py-1 text-cyan-200"><Sparkles size={13} className="mr-2" /> AI-powered campus mobility</Badge><h1 className="max-w-3xl text-5xl font-bold leading-[.98] text-white md:text-7xl">Move smarter.<br /><span className="bg-gradient-to-r from-cyan-200 via-cyan-300 to-blue-400 bg-clip-text text-transparent">Travel together.</span></h1><p className="mt-6 max-w-xl text-lg leading-8 text-slate-400">A calmer way for the SASI community to coordinate routes, discover compatible Smart Pools, and make every campus journey count.</p><div className="mt-8 flex flex-wrap gap-3"><Button onClick={() => go("Find")} className="rounded-full bg-cyan-300 px-5 text-slate-950 hover:bg-cyan-200">Find a ride <ArrowUpRight size={16} className="ml-2" /></Button><Button onClick={() => protectedAction("Create")} variant="outline" className="rounded-full border-white/15 bg-white/5 px-5 text-white hover:bg-white/10">Create Smart Pool</Button><Button onClick={() => go("Routes")} variant="ghost" className="rounded-full text-slate-300 hover:bg-white/10">Explore routes <ChevronRight size={16} /></Button></div><div className="mt-10 flex items-center gap-8 text-sm text-slate-400"><div><strong className="text-2xl text-white">42+</strong><span className="ml-2">routes mapped</span></div><div><strong className="text-2xl text-white">{impact?.tripsReduced ?? 0}</strong><span className="ml-2">trips reduced</span></div></div></div><div className="glass relative overflow-hidden rounded-[2rem] p-5 md:p-7"><div className="absolute right-[-15%] top-[-18%] h-56 w-56 rounded-full bg-cyan-300/10 blur-3xl" /><div className="relative flex items-center justify-between"><div><div className="eyebrow">Live network</div><h3 className="mt-2 text-xl font-semibold text-white">Campus mobility forecast</h3></div><span className="rounded-full border border-emerald-300/20 bg-emerald-300/10 px-2 py-1 text-[11px] text-emerald-200">● Updating</span></div><div className="mt-6 space-y-3">{routes.slice(0, 4).map((route: any, i: number) => <button key={route.id} onClick={() => onRoute(route.id)} className="flex w-full items-center gap-3 rounded-2xl border border-white/5 bg-white/[.035] p-3 text-left hover:border-cyan-300/30 hover:bg-white/[.07]"><span className="grid h-9 w-9 place-items-center rounded-xl bg-cyan-300/10 text-cyan-200"><RouteIcon size={16} /></span><span className="min-w-0 flex-1"><span className="block truncate text-sm font-medium text-white">{route.origin} <span className="text-slate-500">→</span> SASI Campus</span><span className="block text-xs text-slate-500">{route.routeNumber} · {route.stops ? formatStops(route.stops).length : 0} stops</span></span><span className={`rounded-full px-2 py-1 text-[10px] ${i === 0 ? "bg-amber-300/10 text-amber-200" : "bg-cyan-300/10 text-cyan-200"}`}>{i === 0 ? "High demand" : "Balanced"}</span></button>)}{!routes.length && <div className="py-8 text-center text-sm text-slate-500"><Loader2 className="mx-auto mb-2 animate-spin" size={18} />Loading network data…</div>}</div><div className="mt-5 grid grid-cols-3 gap-2 border-t border-white/10 pt-5 text-center"><div><div className="metric-number text-cyan-200">{routes.length || "—"}</div><div className="text-[10px] uppercase tracking-wider text-slate-500">Active routes</div></div><div><div className="metric-number text-white">{pools.length || "—"}</div><div className="text-[10px] uppercase tracking-wider text-slate-500">Open pools</div></div><div><div className="metric-number text-emerald-200">{impact?.co2Saved ?? "—"}</div><div className="text-[10px] uppercase tracking-wider text-slate-500">kg CO₂ saved</div></div></div></div></section><section><SectionHeading eyebrow="Forecast" title="The network, at a glance" action={<button onClick={() => go("Command Center")} className="hidden text-sm text-cyan-200 hover:text-white sm:flex">Open command center <ArrowUpRight size={15} className="ml-1" /></button>} /><div className="grid gap-4 md:grid-cols-3"><MetricCard icon={<Users size={18} />} label="Students connected" value={String(impact?.students ?? 0)} hint="Across active Smart Pools" /><MetricCard icon={<Leaf size={18} />} label="Estimated CO₂ saved" value={`${impact?.co2Saved ?? 0} kg`} hint="Compared with solo trips" /><MetricCard icon={<MapPin size={18} />} label="Most popular route" value={impact?.popularRoute ?? "—"} hint="Based on current pool activity" /></div></section><section><SectionHeading eyebrow="Popular routes" title="Where the network is moving" /><div className="grid gap-3 md:grid-cols-3">{routes.slice(0, 3).map((route: any, index: number) => <button key={route.id} onClick={() => onRoute(route.id)} className="glass rounded-3xl p-5 text-left hover:border-cyan-300/30"><div className="flex items-center justify-between"><span className="text-xs font-bold tracking-widest text-cyan-300">0{index + 1}</span><ArrowUpRight size={16} className="text-slate-500" /></div><h3 className="mt-6 font-semibold text-white">{route.origin} → SASI Campus</h3><p className="mt-2 text-xs text-slate-500">{route.routeNumber} · {formatStops(route.stops).length} stops</p></button>)}</div></section><section><SectionHeading eyebrow="Smart Pools" title="Find your people on the route" action={<button onClick={() => go("Find")} className="text-sm text-cyan-200 hover:text-white">Browse all <ArrowUpRight size={15} className="ml-1 inline" /></button>} /><div className="grid gap-4 md:grid-cols-3">{pools.slice(0, 3).map((p: any) => <PoolCard key={p.pool.id} pool={p} onJoin={() => protectedAction("Find")} />)}{!pools.length && <div className="glass col-span-full rounded-3xl p-10 text-center text-slate-400">No open pools yet. Start one for your route and invite your campus circle.</div>}</div></section><section className="glass grid gap-8 rounded-[2rem] p-7 md:grid-cols-[.8fr_1.2fr] md:p-10"><div><div className="eyebrow">How it works</div><h2 className="mt-3 text-3xl font-bold text-white">One network.<br /><span className="text-cyan-200">Many better journeys.</span></h2><p className="mt-4 max-w-md text-sm leading-7 text-slate-400">SmartRide keeps route information, real-time demand, and shared travel intent in one calm command center.</p></div><div className="grid gap-5 sm:grid-cols-3"><Step n="01" title="Choose your route" text="Find your town, stop, and campus connection." /><Step n="02" title="Join the pool" text="Match by pickup point and departure time." /><Step n="03" title="Make an impact" text="Every shared ride reduces a vehicle trip." /></div></section></div>; }
function MetricCard({ icon, label, value, hint }: any) { return <div className="glass rounded-3xl p-5"><div className="mb-8 grid h-9 w-9 place-items-center rounded-xl bg-cyan-300/10 text-cyan-200">{icon}</div><div className="metric-number text-white">{value}</div><div className="mt-1 text-sm font-medium text-slate-300">{label}</div><div className="mt-2 text-xs text-slate-500">{hint}</div></div>; }
function Step({ n, title, text }: any) { return <div><span className="text-xs font-bold tracking-widest text-cyan-300">{n}</span><h3 className="mt-3 text-base font-semibold text-white">{title}</h3><p className="mt-2 text-sm leading-6 text-slate-500">{text}</p></div>; }
function PoolCard({ pool, onJoin }: any) { return <div className="glass rounded-3xl p-5"><div className="flex items-start justify-between"><span className="rounded-xl bg-cyan-300/10 p-2 text-cyan-200"><Users size={17} /></span><span className="text-xs text-emerald-200">{pool.members.length}/{pool.pool.capacity} seats</span></div><h3 className="mt-5 font-semibold text-white">{pool.route?.origin ?? "Campus"} → SASI Campus</h3><p className="mt-1 text-sm text-slate-400">{pool.pool.pickupPoint} · {pool.pool.departureTime}</p><div className="mt-5 flex items-center justify-between border-t border-white/10 pt-4"><span className="text-xs text-slate-500">{pool.route?.routeNumber}</span><Button onClick={onJoin} size="sm" className="rounded-full bg-white/10 text-cyan-100 hover:bg-cyan-300 hover:text-slate-950">Join pool</Button></div></div>; }
function FindView({ search, setSearch, routeType, setRouteType, rideDate, setRideDate, routes, pools, rides, ridesLoading, ridesError, routeError, onRoute, onJoin, onRequest }: any) { return <div className="space-y-8"><div><div className="eyebrow">Discover</div><h1 className="mt-2 text-4xl font-bold text-white">Find your next ride.</h1><p className="mt-3 text-slate-400">Search by town, stop, route number, or destination.</p></div><div className="glass flex items-center gap-3 rounded-2xl p-3"><Search size={20} className="ml-2 text-cyan-300" /><Input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Try ‘Eluru’, ‘SR-12’, or ‘Railway Station’" className="border-0 bg-transparent text-white shadow-none focus-visible:ring-0" /><Badge variant="outline" className="hidden whitespace-nowrap border-white/10 text-slate-400 sm:flex">{routes.length} routes</Badge></div><div className="flex flex-wrap items-center gap-2"><button onClick={() => setRouteType("all")} className={`rounded-full px-3 py-1.5 text-xs ${routeType === "all" ? "bg-cyan-300 text-slate-950" : "bg-white/5 text-slate-400"}`}>All</button><button onClick={() => setRouteType("campus")} className={`rounded-full px-3 py-1.5 text-xs ${routeType === "campus" ? "bg-cyan-300 text-slate-950" : "bg-white/5 text-slate-400"}`}>Campus</button><button onClick={() => setRouteType("local")} className={`rounded-full px-3 py-1.5 text-xs ${routeType === "local" ? "bg-cyan-300 text-slate-950" : "bg-white/5 text-slate-400"}`}>Local</button><label className="ml-auto flex items-center gap-2 text-xs text-slate-500">Date<Input type="date" value={rideDate} onChange={(e) => setRideDate(e.target.value)} className="h-8 w-auto border-white/10 bg-white/5 text-slate-200" /></label></div>{routeError && <div className="rounded-2xl border border-rose-300/20 bg-rose-300/10 px-4 py-3 text-sm text-rose-100">Route data could not be loaded. Please refresh and try again.</div>}<div><SectionHeading eyebrow="Route directory" title="All SASI connections" /><div className="grid gap-3 md:grid-cols-2">{routes.map((route: any) => <button key={route.id} onClick={() => onRoute(route.id)} className="glass group flex items-center gap-4 rounded-3xl p-5 text-left hover:-translate-y-0.5 hover:border-cyan-300/30"><span className="grid h-11 w-11 shrink-0 place-items-center rounded-2xl bg-cyan-300/10 text-cyan-200"><RouteIcon size={19} /></span><span className="min-w-0 flex-1"><span className="block text-sm font-semibold text-white">{route.origin} <span className="text-slate-500">→</span> SASI Campus</span><span className="mt-1 block truncate text-xs text-slate-500">{route.routeNumber} · {route.routeName}</span></span><ChevronRight className="text-slate-600 group-hover:text-cyan-200" size={18} /></button>)}{!routes.length && <div className="glass col-span-full rounded-3xl p-10 text-center text-slate-400"><Loader2 className="mx-auto mb-3 animate-spin" />Syncing route directory…</div>}</div></div><div><SectionHeading eyebrow="Ride matches" title="Journeys that fit your route" /><div className="grid gap-4 md:grid-cols-2">{!ridesLoading && !ridesError && rides.map((item: any) => <RideMatchCard key={item.ride.id} item={item} onRequest={onRequest} />)}{ridesLoading && <div className="glass col-span-full rounded-3xl p-10 text-center text-slate-400"><Loader2 className="mx-auto mb-3 animate-spin" />Searching available rides…</div>}{ridesError && <div className="col-span-full rounded-2xl border border-rose-300/20 bg-rose-300/10 px-4 py-3 text-sm text-rose-100">Ride matches could not be loaded. Please try again.</div>}{!ridesLoading && !ridesError && !rides.length && <div className="glass col-span-full rounded-3xl p-10 text-center text-slate-500">No rides match this search yet. Try another route or create a ride.</div>}</div></div><div><SectionHeading eyebrow="Compatible now" title="Open Smart Pools" /><div className="grid gap-4 md:grid-cols-3">{pools.map((p: any) => <PoolCard key={p.pool.id} pool={p} onJoin={() => onJoin(p.pool.id)} />)}{!pools.length && <div className="glass col-span-full rounded-3xl p-10 text-center text-slate-500">No matching Smart Pools yet. Create the first one for your route.</div>}</div></div></div>; }
function RideMatchCard({ item, onRequest }: any) { const { ride, route, creator } = item; const verified = creator?.verificationStatus === "verified"; return <div className="glass rounded-3xl p-5"><div className="flex items-start justify-between gap-3"><div className="flex items-center gap-3"><span className="grid h-10 w-10 place-items-center overflow-hidden rounded-xl bg-cyan-300/10 text-cyan-200">{creator?.profileImage ? <img src={creator.profileImage} alt="" className="h-full w-full object-cover" /> : <RouteIcon size={17} />}</span><div><div className="text-sm font-semibold text-white">{creator?.name ?? "SmartRide student"}</div><div className="text-xs text-slate-500">{verified ? "✓ Verified Student" : "Verification pending"}</div></div></div><span className="text-xs text-emerald-200">{ride.availableSeats} seats</span></div><div className="mt-5 flex items-center justify-between"><h3 className="font-semibold text-white">{route?.origin ?? "Route"} → {ride.destination}</h3><span className="rounded-full bg-cyan-300/10 px-2 py-1 text-xs font-semibold text-cyan-200">{item.matchScore}% Match</span></div><p className="mt-1 text-sm text-slate-400">{route?.routeNumber ?? "SmartRide"} · {ride.pickupPoint}</p><div className="mt-3 flex flex-wrap gap-2 text-xs text-slate-500">{(item.matchReasons ?? []).map((reason: string) => <span key={reason} className="rounded-full bg-white/5 px-2 py-1">{reason}</span>)}</div><div className="mt-4 flex items-center justify-between border-t border-white/10 pt-4 text-xs text-slate-500"><span>{ride.date} · {ride.time}</span><Button onClick={() => onRequest?.(ride.id)} size="sm" className="rounded-full bg-cyan-300 text-slate-950 hover:bg-cyan-200">Request seat</Button></div></div>; }
function RouteDetail({ route, pools, onBack }: any) { const stops = formatStops(route.stops); return <div className="space-y-8"><button onClick={onBack} className="text-sm text-cyan-200">← Back to routes</button><div className="glass rounded-[2rem] p-7 md:p-10"><div className="flex flex-wrap items-start justify-between gap-4"><div><div className="eyebrow">{route.routeNumber} · {route.routeType} connection</div><h1 className="mt-3 text-4xl font-bold text-white">{route.origin} <span className="text-cyan-300">→</span> SASI Campus</h1><p className="mt-3 text-slate-400">{route.routeName}</p></div><Badge className="bg-emerald-300/10 text-emerald-200">Live route</Badge></div><div className="mt-10 grid gap-10 md:grid-cols-[1fr_.8fr]"><div><div className="eyebrow mb-5">Route timeline</div>{stops.map((stop, index) => <div className="route-line flex gap-4 pb-7" key={stop}><span className="relative z-10 grid h-5 w-5 shrink-0 place-items-center rounded-full border border-cyan-300/50 bg-[#10243a]"><span className="h-1.5 w-1.5 rounded-full bg-cyan-300" /></span><div><div className="text-sm font-medium text-white">{stop}</div><div className="mt-1 text-xs text-slate-500">{index === 0 ? "Origin pickup" : index === stops.length - 1 ? "Campus arrival" : "Scheduled stop"}</div></div></div>)}</div><div className="space-y-4"><div className="rounded-2xl border border-white/10 bg-white/[.03] p-5"><div className="text-xs uppercase tracking-wider text-slate-500">Active Smart Pools</div><div className="mt-2 text-3xl font-bold text-white">{pools.length}</div><div className="mt-1 text-sm text-slate-400">Matching this route today</div></div><div className="rounded-2xl border border-white/10 bg-white/[.03] p-5"><div className="text-xs uppercase tracking-wider text-slate-500">Pickup intelligence</div><div className="mt-2 text-sm leading-6 text-cyan-100">Prioritised by exact stop, then nearby stops and towns.</div></div></div></div></div></div>; }
function CreateView({ routes, poolForm, setPoolForm, rideForm, setRideForm, onCreatePool, onCreateRide, busy }: any) { return <div className="space-y-8"><div><div className="eyebrow">Create</div><h1 className="mt-2 text-4xl font-bold text-white">Put a better journey in motion.</h1><p className="mt-3 text-slate-400">Share a ride or start a Smart Pool for your route.</p></div><div className="grid gap-5 lg:grid-cols-2"><FormCard title="Create a Smart Pool" subtitle="Coordinate seats around a shared departure."><Field label="Route"><select value={poolForm.routeId} onChange={(e) => setPoolForm({ ...poolForm, routeId: e.target.value })} className="h-10 w-full rounded-md border border-white/10 bg-white/5 px-3 text-sm text-white"><option value="">Select route</option>{routes.map((r: any) => <option className="bg-[#10213a]" key={r.id} value={r.id}>{r.routeNumber} · {r.origin}</option>)}</select></Field><Field label="Pickup point"><Input value={poolForm.pickupPoint} onChange={(e) => setPoolForm({ ...poolForm, pickupPoint: e.target.value })} placeholder="e.g. Railway Station" /></Field><div className="grid grid-cols-2 gap-3"><Field label="Departure"><Input type="time" value={poolForm.departureTime} onChange={(e) => setPoolForm({ ...poolForm, departureTime: e.target.value })} /></Field><Field label="Capacity"><Input type="number" min="2" max="8" value={poolForm.capacity} onChange={(e) => setPoolForm({ ...poolForm, capacity: e.target.value })} /></Field></div><Button disabled={busy} onClick={onCreatePool} className="mt-2 w-full rounded-xl bg-cyan-300 text-slate-950 hover:bg-cyan-200">{busy ? <Loader2 className="animate-spin" /> : <Plus size={16} />} Start Smart Pool</Button></FormCard><FormCard title="Create a ride" subtitle="Offer seats and make your route more efficient."><Field label="Route"><select value={rideForm.routeId} onChange={(e) => setRideForm({ ...rideForm, routeId: e.target.value })} className="h-10 w-full rounded-md border border-white/10 bg-white/5 px-3 text-sm text-white"><option value="">Select route</option>{routes.map((r: any) => <option className="bg-[#10213a]" key={r.id} value={r.id}>{r.routeNumber} · {r.origin}</option>)}</select></Field><div className="grid grid-cols-2 gap-3"><Field label="Pickup point"><Input value={rideForm.pickupPoint} onChange={(e) => setRideForm({ ...rideForm, pickupPoint: e.target.value })} placeholder="Town stop" /></Field><Field label="Seats"><Input type="number" min="1" max="8" value={rideForm.availableSeats} onChange={(e) => setRideForm({ ...rideForm, availableSeats: e.target.value })} /></Field></div><div className="grid grid-cols-2 gap-3"><Field label="Date"><Input type="date" value={rideForm.date} onChange={(e) => setRideForm({ ...rideForm, date: e.target.value })} /></Field><Field label="Time"><Input type="time" value={rideForm.time} onChange={(e) => setRideForm({ ...rideForm, time: e.target.value })} /></Field></div><div className="grid grid-cols-3 gap-3"><Field label="Vehicle"><select value={rideForm.vehicleType} onChange={(e) => setRideForm({ ...rideForm, vehicleType: e.target.value })} className="h-10 w-full rounded-md border border-white/10 bg-white/5 px-2 text-sm text-white"><option className="bg-[#10213a]">Car</option><option className="bg-[#10213a]">Bike</option><option className="bg-[#10213a]">Auto</option></select></Field><Field label="Gender preference"><select value={rideForm.genderPreference} onChange={(e) => setRideForm({ ...rideForm, genderPreference: e.target.value })} className="h-10 w-full rounded-md border border-white/10 bg-white/5 px-2 text-sm text-white"><option className="bg-[#10213a]">any</option><option className="bg-[#10213a]">same-gender</option></select></Field><Field label="Contact"><select value={rideForm.contactPreference} onChange={(e) => setRideForm({ ...rideForm, contactPreference: e.target.value })} className="h-10 w-full rounded-md border border-white/10 bg-white/5 px-2 text-sm text-white"><option className="bg-[#10213a]">In-app</option><option className="bg-[#10213a]">Phone</option></select></Field></div><Field label="Notes"><Textarea value={rideForm.notes} onChange={(e) => setRideForm({ ...rideForm, notes: e.target.value })} placeholder="Anything your co-riders should know?" /></Field><Button disabled={busy} onClick={onCreateRide} className="mt-2 w-full rounded-xl bg-white/10 text-white hover:bg-cyan-300 hover:text-slate-950">{busy ? <Loader2 className="animate-spin" /> : <Plus size={16} />} Publish ride</Button></FormCard></div></div>; }
function FormCard({ title, subtitle, children }: any) { return <div className="glass rounded-[2rem] p-6 md:p-8"><h2 className="text-xl font-semibold text-white">{title}</h2><p className="mt-2 text-sm text-slate-500">{subtitle}</p><div className="mt-7 space-y-4">{children}</div></div>; }
function Field({ label, children }: any) { return <label className="block text-sm text-slate-300"><span className="mb-2 block text-xs uppercase tracking-wider text-slate-500">{label}</span>{children}</label>; }
function RidesView({ rides, joinedPools, loading, error, onCancel, onLeave }: any) { const [tab, setTab] = useState("Upcoming"); const visible = rides.filter((item: any) => tab === "Created" ? true : tab === "Upcoming" ? item.ride.status === "upcoming" : item.ride.status === tab.toLowerCase()); return <div className="space-y-8"><div><div className="eyebrow">Your movement</div><h1 className="mt-2 text-4xl font-bold text-white">My Rides</h1><p className="mt-3 text-slate-400">Your upcoming and shared journeys in one place.</p></div><div className="flex gap-2 overflow-auto border-b border-white/10 pb-3 text-sm">{["Upcoming", "Created", "Joined", "Completed", "Cancelled"].map((item) => <button key={item} onClick={() => setTab(item)} className={`rounded-full px-3 py-1.5 ${tab === item ? "bg-cyan-300/10 text-cyan-200" : "text-slate-500"}`}>{item}</button>)}</div>{error && <div className="rounded-2xl border border-rose-300/20 bg-rose-300/10 px-4 py-3 text-sm text-rose-100">Your rides could not be loaded. Please try again.</div>}{tab === "Joined" ? <div className="space-y-3">{joinedPools.map((item: any) => <div key={item.pool.id} className="glass flex flex-wrap items-center gap-4 rounded-3xl p-5"><span className="grid h-11 w-11 place-items-center rounded-2xl bg-cyan-300/10 text-cyan-200"><Users size={18} /></span><div className="min-w-0 flex-1"><div className="font-medium text-white">{item.route?.origin} → SASI Campus</div><div className="mt-1 text-xs text-slate-500">{item.pool.departureTime} · {item.pool.pickupPoint}</div></div><Button onClick={() => onLeave(item.pool.id)} size="sm" variant="ghost" className="text-rose-200">Leave pool</Button></div>)}</div> : loading ? <div className="glass rounded-3xl p-10 text-center text-slate-400"><Loader2 className="mx-auto animate-spin" /></div> : visible.length ? <div className="space-y-3">{visible.map((item: any) => <div className="glass flex flex-wrap items-center gap-4 rounded-3xl p-5" key={item.ride.id}><span className="grid h-11 w-11 place-items-center rounded-2xl bg-cyan-300/10 text-cyan-200"><RouteIcon size={18} /></span><div className="min-w-0 flex-1"><div className="font-medium text-white">{item.route?.origin} → SASI Campus</div><div className="mt-1 text-xs text-slate-500">{item.ride.date} at {item.ride.time} · {item.ride.pickupPoint}</div></div><div className="flex items-center gap-2"><Badge className="bg-cyan-300/10 text-cyan-200">{item.ride.status}</Badge>{item.ride.status === "upcoming" && <Button onClick={() => onCancel(item.ride.id)} size="sm" variant="ghost" className="text-rose-200 hover:bg-rose-300/10">Cancel</Button>}</div></div>)}</div> : <div className="glass rounded-[2rem] p-12 text-center"><RouteIcon className="mx-auto mb-4 text-slate-600" size={30} /><h3 className="text-lg font-semibold text-white">Your ride board is clear.</h3><p className="mx-auto mt-2 max-w-sm text-sm leading-6 text-slate-500">Create a ride or join a Smart Pool to see your upcoming journeys here.</p></div>}</div>; }
function ImpactView({ impact, error }: any) { return <div className="space-y-8">{error && <div className="rounded-2xl border border-rose-300/20 bg-rose-300/10 px-4 py-3 text-sm text-rose-100">Impact data is temporarily unavailable.</div>}<div><div className="eyebrow">Sustainability</div><h1 className="mt-2 text-4xl font-bold text-white">Every shared seat counts.</h1><p className="mt-3 max-w-xl text-slate-400">SmartRide turns everyday campus movement into measurable collective progress.</p></div><div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4"><MetricCard icon={<Users size={18} />} label="Smart Pools created" value={String(impact?.pools ?? 0)} hint="Community-led journeys" /><MetricCard icon={<Users size={18} />} label="Students connected" value={String(impact?.students ?? 0)} hint="Across the network" /><MetricCard icon={<RouteIcon size={18} />} label="Trips reduced" value={String(impact?.tripsReduced ?? 0)} hint="Estimated shared trips" /><MetricCard icon={<Leaf size={18} />} label="CO₂ saved" value={`${impact?.co2Saved ?? 0} kg`} hint="Estimated impact" /></div><div className="glass rounded-[2rem] p-7 md:p-10"><div className="flex flex-wrap items-end justify-between gap-4"><div><div className="eyebrow">Network signal</div><h2 className="mt-2 text-2xl font-semibold text-white">Shared movement is the new infrastructure.</h2></div><div className="text-right"><div className="metric-number text-cyan-200">{impact?.averagePoolSize ?? 0}×</div><div className="text-xs text-slate-500">average pool size</div></div></div><div className="mt-10 h-32 overflow-hidden rounded-2xl border border-cyan-300/10 bg-gradient-to-r from-cyan-300/10 via-blue-400/10 to-transparent"><div className="mt-16 h-px w-full bg-gradient-to-r from-transparent via-cyan-300 to-transparent shadow-[0_0_20px_#2ce5d4]" /></div></div></div>; }
function CommandView() { const q = trpc.commandCenter.summary.useQuery(); const d = q.data; return <div className="space-y-8">{q.isError && <div className="rounded-2xl border border-rose-300/20 bg-rose-300/10 px-4 py-3 text-sm text-rose-100">Command center metrics are temporarily unavailable.</div>}<div><div className="eyebrow">Operations</div><h1 className="mt-2 text-4xl font-bold text-white">Mobility command center.</h1><p className="mt-3 text-slate-400">A live operational read on the SASI mobility network.</p></div><div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4"><MetricCard icon={<RouteIcon size={18} />} label="Active routes" value={String(d?.activeRoutes ?? 0)} hint="Mapped campus connections" /><MetricCard icon={<Users size={18} />} label="Active pools" value={String(d?.activePools ?? 0)} hint="Open for matching" /><MetricCard icon={<MapPin size={18} />} label="Available seats" value={String(d?.availableSeats ?? 0)} hint="Ready to be shared" /><MetricCard icon={<Sparkles size={18} />} label="Students searching" value={String(d?.studentsSearching ?? 0)} hint="Current pool members" /></div><div className="glass rounded-[2rem] p-8"><div className="flex items-center justify-between"><div><div className="eyebrow">Demand distribution</div><h2 className="mt-2 text-2xl font-semibold text-white">Route activity map</h2></div><Badge className="bg-cyan-300/10 text-cyan-200">Live</Badge></div><div className="mt-8 grid gap-3 sm:grid-cols-5">{["Palakollu", "Eluru", "Bhimavaram", "Tanuku", "Tadepalligudem"].map((town, i) => <div key={town}><div className="mb-2 flex justify-between text-xs text-slate-500"><span>{town}</span><span>{82 - i * 11}%</span></div><div className="h-2 rounded-full bg-white/5"><div className="h-2 rounded-full bg-gradient-to-r from-cyan-300 to-blue-400" style={{ width: `${82 - i * 11}%` }} /></div></div>)}</div></div></div>; }
function ProfileView({ profile, error, routes, onSave, busy }: any) { const [name, setName] = useState(profile?.name ?? ""); const [city, setCity] = useState(profile?.city ?? ""); const [college, setCollege] = useState(profile?.college ?? ""); const [course, setCourse] = useState(profile?.course ?? ""); const [pickupPoint, setPickupPoint] = useState(profile?.pickupPoint ?? ""); const [interests, setInterests] = useState(profile?.interests ?? ""); const [routeId, setRouteId] = useState(String(profile?.routeId ?? "")); const [profileImage, setProfileImage] = useState(profile?.profileImage ?? ""); const [phoneNumber, setPhoneNumber] = useState(profile?.phoneNumber ?? ""); const [studyYear, setStudyYear] = useState(profile?.studyYear ?? ""); const [gender, setGender] = useState(profile?.gender ?? ""); const [genderPreference, setGenderPreference] = useState(profile?.genderPreference ?? "any"); const [bio, setBio] = useState(profile?.bio ?? ""); useEffect(() => { setName(profile?.name ?? ""); setCity(profile?.city ?? ""); setCollege(profile?.college ?? ""); setCourse(profile?.course ?? ""); setPickupPoint(profile?.pickupPoint ?? ""); setInterests(profile?.interests ?? ""); setRouteId(String(profile?.routeId ?? "")); setProfileImage(profile?.profileImage ?? ""); setPhoneNumber(profile?.phoneNumber ?? ""); setStudyYear(profile?.studyYear ?? ""); setGender(profile?.gender ?? ""); setGenderPreference(profile?.genderPreference ?? "any"); setBio(profile?.bio ?? ""); }, [profile]); return <div className="max-w-2xl space-y-8">{error && <div className="rounded-2xl border border-rose-300/20 bg-rose-300/10 px-4 py-3 text-sm text-rose-100">Profile data could not be loaded.</div>}<div><div className="eyebrow">Your profile</div><h1 className="mt-2 text-4xl font-bold text-white">Make the network yours.</h1><p className="mt-3 text-slate-400">Your profile helps SmartRide match you with the right route and people.</p></div><div className="glass rounded-[2rem] p-7 md:p-9"><div className="grid gap-5"><Field label="Name"><Input value={name} onChange={(e) => setName(e.target.value)} /></Field><Field label="Email"><Input disabled value={profile?.email ?? ""} /></Field><Field label="City"><Input value={city} onChange={(e) => setCity(e.target.value)} placeholder="Tadepalligudem" /></Field><div className="grid gap-4 sm:grid-cols-2"><Field label="College"><Input value={college} onChange={(e) => setCollege(e.target.value)} placeholder="SASI Institute" /></Field><Field label="Course"><Input value={course} onChange={(e) => setCourse(e.target.value)} placeholder="Computer Science" /></Field></div><Field label="Preferred route"><select value={routeId} onChange={(e) => setRouteId(e.target.value)} className="h-10 w-full rounded-md border border-white/10 bg-white/5 px-3 text-sm text-white"><option value="">Choose a route</option>{routes.map((r: any) => <option className="bg-[#10213a]" key={r.id} value={r.id}>{r.routeNumber} · {r.origin}</option>)}</select></Field><Field label="Profile image URL"><Input value={profileImage} onChange={(e) => setProfileImage(e.target.value)} placeholder="https://…" /></Field><div className="grid gap-4 sm:grid-cols-2"><Field label="Phone number"><Input value={phoneNumber} onChange={(e) => setPhoneNumber(e.target.value)} placeholder="Optional contact number" /></Field><Field label="Year"><Input value={studyYear} onChange={(e) => setStudyYear(e.target.value)} placeholder="2nd year" /></Field></div><div className="grid gap-4 sm:grid-cols-2"><Field label="Gender"><Input value={gender} onChange={(e) => setGender(e.target.value)} placeholder="Optional" /></Field><Field label="Match preference"><select value={genderPreference} onChange={(e) => setGenderPreference(e.target.value)} className="h-10 w-full rounded-md border border-white/10 bg-white/5 px-3 text-sm text-white"><option className="bg-[#10213a]">any</option><option className="bg-[#10213a]">same-gender</option></select></Field></div><div className="rounded-2xl border border-white/10 bg-white/[.03] px-4 py-3 text-sm text-slate-400">{profile?.verificationStatus === "verified" ? "✓ Verified Student" : "Verification pending — complete the defined verification flow when available."}</div><Field label="Preferred pickup point"><Input value={pickupPoint} onChange={(e) => setPickupPoint(e.target.value)} placeholder="Railway Station" /></Field><Field label="Interests"><Input value={interests} onChange={(e) => setInterests(e.target.value)} placeholder="Cycling, music, coding" /></Field><Field label="Bio"><Textarea value={bio} onChange={(e) => setBio(e.target.value)} placeholder="A little about your campus journey" /></Field><Button disabled={busy} onClick={() => onSave({ name, city, college, course, pickupPoint, interests, routeId: routeId ? Number(routeId) : null, profileImage, phoneNumber, studyYear, gender, genderPreference, bio })} className="mt-2 rounded-xl bg-cyan-300 text-slate-950 hover:bg-cyan-200">{busy ? <Loader2 className="animate-spin" /> : "Save profile"}</Button></div></div></div>; }
function NotificationsView() { const q = trpc.notifications.list.useQuery(); const utils = trpc.useUtils(); const markRead = trpc.notifications.markRead.useMutation({ onSuccess: () => utils.notifications.list.invalidate() }); const markAllRead = trpc.notifications.markAllRead.useMutation({ onSuccess: () => utils.notifications.list.invalidate() }); const unread = (q.data ?? []).filter((n) => !n.read).length; return <div className="space-y-8"><div className="flex items-end justify-between gap-4"><div><div className="eyebrow">Updates</div><h1 className="mt-2 text-4xl font-bold text-white">Notifications</h1><p className="mt-3 text-slate-400">{unread ? `${unread} unread update${unread === 1 ? "" : "s"}` : "You are up to date."}</p></div>{unread > 0 && <Button onClick={() => markAllRead.mutate()} variant="ghost" className="text-cyan-200">Mark all read</Button>}</div><div className="space-y-3">{q.isError && <div className="rounded-2xl border border-rose-300/20 bg-rose-300/10 px-4 py-3 text-sm text-rose-100">Notifications could not be loaded.</div>}{q.isLoading ? <div className="glass rounded-3xl p-10 text-center"><Loader2 className="mx-auto animate-spin" /></div> : (q.data ?? []).map((n) => <div key={n.id} className={`glass flex gap-4 rounded-3xl p-5 ${n.read ? "opacity-60" : ""}`}><Bell className="mt-1 text-cyan-300" size={18} /><div className="min-w-0 flex-1"><p className="text-sm text-white">{n.message}</p><p className="mt-1 text-xs text-slate-500">{new Date(n.createdAt).toLocaleString()}</p></div>{!n.read && <Button onClick={() => markRead.mutate({ id: n.id })} size="sm" variant="ghost" className="text-cyan-200">Mark read</Button>}</div>)}{!q.isLoading && !q.data?.length && <div className="glass rounded-[2rem] p-12 text-center text-slate-500">You are all caught up.</div>}</div></div>; }

function MatchesView({ rides, loading, error, onRequest }: any) { return <div className="space-y-8"><div><div className="eyebrow">Smart matching</div><h1 className="mt-2 text-4xl font-bold text-white">Your strongest matches.</h1><p className="mt-3 max-w-xl text-slate-400">Deterministic scores use stored route, pickup, town, preference, and seat data.</p></div>{error && <div className="rounded-2xl border border-rose-300/20 bg-rose-300/10 px-4 py-3 text-sm text-rose-100">Matches could not be loaded.</div>}{loading ? <div className="glass rounded-3xl p-10 text-center text-slate-400"><Loader2 className="mx-auto animate-spin" /></div> : rides.length ? <div className="grid gap-4 md:grid-cols-2">{[...rides].sort((a: any, b: any) => (b.matchScore ?? 0) - (a.matchScore ?? 0)).map((item: any) => <RideMatchCard key={item.ride.id} item={item} onRequest={onRequest} />)}</div> : <div className="glass rounded-[2rem] p-12 text-center"><Sparkles className="mx-auto mb-4 text-cyan-300" size={30} /><h3 className="text-lg font-semibold text-white">No matches yet</h3><p className="mx-auto mt-2 max-w-sm text-sm leading-6 text-slate-500">Add your route and pickup preferences to discover compatible rides.</p></div>}</div>; }
function SettingsView({ profile }: any) { const completion = [profile?.name, profile?.college, profile?.course, profile?.city, profile?.pickupPoint, profile?.routeId, profile?.phoneNumber, profile?.gender].filter(Boolean).length; const percent = Math.round((completion / 8) * 100); return <div className="max-w-2xl space-y-8"><div><div className="eyebrow">Account settings</div><h1 className="mt-2 text-4xl font-bold text-white">A clearer way to move.</h1><p className="mt-3 text-slate-400">Review your account readiness and privacy posture.</p></div><div className="glass rounded-[2rem] p-7 md:p-9"><div className="flex items-end justify-between"><div><div className="eyebrow">Profile completion</div><div className="mt-2 text-4xl font-bold text-white">{percent}%</div></div><span className="text-sm text-cyan-200">{profile?.verificationStatus === "verified" ? "✓ Verified Student" : "Verification pending"}</span></div><div className="mt-5 h-2 rounded-full bg-white/5"><div className="h-2 rounded-full bg-gradient-to-r from-cyan-300 to-emerald-300" style={{ width: `${percent}%` }} /></div><p className="mt-4 text-sm leading-6 text-slate-500">Complete your profile to improve matching quality. You can edit college, course, route, pickup point, and verification details from Profile.</p></div><div className="glass rounded-[2rem] p-7"><div className="eyebrow">Privacy</div><h2 className="mt-2 text-xl font-semibold text-white">Your data stays scoped to your account.</h2><p className="mt-3 text-sm leading-6 text-slate-500">Ride requests and notifications are only visible to the authenticated account involved in the journey.</p></div></div>; }

function RequestBoard({ requests, loading, onRequestStatus }: any) { const received = requests?.received ?? []; const mine = requests?.mine ?? []; return <section className="space-y-5"><SectionHeading eyebrow="Ride requests" title="Keep every journey coordinated" /><div className="grid gap-4 lg:grid-cols-2"><div className="glass rounded-[2rem] p-6"><h3 className="font-semibold text-white">Requests for your rides</h3>{loading ? <Loader2 className="mt-6 animate-spin text-cyan-300" /> : received.length ? <div className="mt-5 space-y-3">{received.map((item: any) => <div key={item.request.id} className="rounded-2xl border border-white/10 bg-white/[.03] p-4"><div className="flex items-start justify-between gap-3"><div><div className="text-sm font-medium text-white">{item.requester?.name ?? "Student request"}</div><div className="mt-1 text-xs text-slate-500">{item.route?.origin ?? "Route"} · {item.ride?.date} at {item.ride?.time}</div></div><Badge className="bg-cyan-300/10 text-cyan-200">{item.request.status}</Badge></div>{item.request.status === "pending" && <div className="mt-3 flex gap-2"><Button size="sm" onClick={() => onRequestStatus(item.request.id, "accepted")} className="rounded-full bg-cyan-300 text-slate-950">Accept</Button><Button size="sm" variant="ghost" onClick={() => onRequestStatus(item.request.id, "rejected")} className="rounded-full text-rose-200">Reject</Button></div>}</div>)}</div> : <p className="mt-5 text-sm text-slate-500">No ride requests yet.</p>}</div><div className="glass rounded-[2rem] p-6"><h3 className="font-semibold text-white">Your sent requests</h3>{loading ? <Loader2 className="mt-6 animate-spin text-cyan-300" /> : mine.length ? <div className="mt-5 space-y-3">{mine.map((item: any) => <div key={item.request.id} className="rounded-2xl border border-white/10 bg-white/[.03] p-4"><div className="flex items-start justify-between gap-3"><div><div className="text-sm font-medium text-white">{item.route?.origin ?? "Route"} → {item.ride?.destination}</div><div className="mt-1 text-xs text-slate-500">{item.ride?.date} at {item.ride?.time}</div></div><Badge className="bg-cyan-300/10 text-cyan-200">{item.request.status}</Badge></div>{item.request.status === "pending" && <Button size="sm" variant="ghost" onClick={() => onRequestStatus(item.request.id, "cancelled")} className="mt-3 rounded-full text-rose-200">Cancel request</Button>}</div>)}</div> : <p className="mt-5 text-sm text-slate-500">You have not requested a seat yet.</p>}</div></div></section>; }
